clear;
clc;
close all;

%% ============================================================
%  CAN LOG ANALYZER
%  Input:
%       Idle.txt
%       RPM_naik.txt
% =============================================================

%%
idleFile = 'Idle.txt';
rpmFile  = 'RPM_naik.txt';
%%
idle = readCANLog(idleFile);
rpm  = readCANLog(rpmFile);

fprintf('Idle frames: %d\n', height(idle)); %[output:17b563af]
fprintf('RPM frames : %d\n', height(rpm)); %[output:051d81d2]
%%

%%
%% ============================================================
% SHOW ALL CAN IDs
% =============================================================

idleIDs = unique(idle.ID);
rpmIDs  = unique(rpm.ID);

fprintf('\n===== IDLE CAN IDs =====\n'); %[output:5254bbdd]

for i = 1:length(idleIDs) %[output:group:7e65c7fa]
    fprintf('0x%X\n', idleIDs(i)); %[output:3f48684d]
end %[output:group:7e65c7fa]

fprintf('\n===== RPM-UP CAN IDs =====\n'); %[output:49f55d04]

for i = 1:length(rpmIDs) %[output:group:8cfc3f84]
    fprintf('0x%X\n', rpmIDs(i)); %[output:09a5c94a]
end %[output:group:8cfc3f84]
%%
%% ============================================================
% SELECT A CAN ID TO INVESTIGATE
% ============================================================

selectedID = hex2dec('11F');

idleID = idle(idle.ID == selectedID, :);
rpmID  = rpm(rpm.ID == selectedID, :);

fprintf('\nInvestigating CAN ID: 0x%X\n', selectedID); %[output:4272d900]
fprintf('Idle frames: %d\n', height(idleID)); %[output:597bbdc8]
fprintf('RPM frames : %d\n', height(rpmID)); %[output:61819ba7]

%%
%% ============================================================
% PLOT ALL 8 BYTES - RPM UP
% ============================================================

figure; %[output:805b9118]

for byte = 1:8

    subplot(4,2,byte); %[output:805b9118]

    plot(rpmID.Time, rpmID.Data(:,byte), '.-');

    grid on;

    xlabel('Time [s]');
    ylabel(sprintf('Byte %d', byte));

    title(sprintf('CAN 0x%X - Byte %d', selectedID, byte));

end

sgtitle(sprintf('CAN ID 0x%X - RPM UP', selectedID)); %[output:805b9118]
%%

%% ============================================================
% PLOT ALL 8 BYTES - IDLE
% ============================================================

figure; %[output:1a32217e]

for byte = 1:8

    subplot(4,2,byte); %[output:1a32217e]

    plot(idleID.Time, idleID.Data(:,byte), '.-');

    grid on;

    xlabel('Time [s]');
    ylabel(sprintf('Byte %d', byte));

    title(sprintf('CAN 0x%X - Byte %d', selectedID, byte));

end

sgtitle(sprintf('CAN ID 0x%X - IDLE', selectedID)); %[output:1a32217e]


%%
%% ============================================================
% COMPARE IDLE VS RPM-UP
% ============================================================

figure; %[output:61675d4b]

for byte = 1:8

    subplot(4,2,byte); %[output:61675d4b]

    plot(idleID.Time, idleID.Data(:,byte), '.');
    hold on;

    plot(rpmID.Time, rpmID.Data(:,byte), '.');

    grid on;

    xlabel('Time [s]');
    ylabel(sprintf('Byte %d', byte));

    title(sprintf('Byte %d', byte));

    legend('Idle','RPM Up');

end

sgtitle(sprintf('Idle vs RPM-Up - CAN ID 0x%X', selectedID)); %[output:61675d4b]


%% ============================================================
% 16-BIT SIGNAL TEST
% ============================================================

% Example: Bytes 4 and 5
%
% MATLAB indexing:
% Byte 4 = Data(:,4)
% Byte 5 = Data(:,5)

idle_raw = double(idleID.Data(:,4)) + ...
           256*double(idleID.Data(:,5));

rpm_raw = double(rpmID.Data(:,4)) + ...
          256*double(rpmID.Data(:,5));


figure; %[output:0bb338bf]

plot(idleID.Time, idle_raw, '.'); %[output:0bb338bf]
hold on; %[output:0bb338bf]

plot(rpmID.Time, rpm_raw, '.'); %[output:0bb338bf]

grid on; %[output:0bb338bf]

xlabel('Time [s]'); %[output:0bb338bf]
ylabel('Raw 16-bit value'); %[output:0bb338bf]

title(sprintf('CAN 0x%X - Bytes 4-5 Little Endian', selectedID)); %[output:0bb338bf]

legend('Idle','RPM Up'); %[output:0bb338bf]
%%

%% ============================================================
% FUNCTION TO READ CANGAROO TXT
% ============================================================

function T = readCANLog(filename)

    fid = fopen(filename,'r');

    if fid == -1
        error('Cannot open file: %s', filename);
    end

    % Skip header
    fgetl(fid);

    ID = [];
    Time = [];
    Data = [];

    while ~feof(fid)

        line = fgetl(fid);

        if ~ischar(line)
            continue;
        end

        % Extract timestamp
        timeToken = regexp(line, ...
            '\d+:\d+:\d+\s+\d+', ...
            'match', 'once');

        % Extract CAN ID
        idToken = regexp(line, ...
            '0x[0-9A-Fa-f]+', ...
            'match', 'once');

        % Extract data after DLC
        dataToken = regexp(line, ...
            '([0-9A-Fa-f]{2}(?:\s+[0-9A-Fa-f]{2})*)\s*$', ...
            'match', 'once');

        if isempty(timeToken) || ...
           isempty(idToken) || ...
           isempty(dataToken)

            continue;
        end

        %% Time

        timeParts = sscanf(timeToken, ...
            '%d:%d:%d %d');

        h  = timeParts(1);
        m  = timeParts(2);
        s  = timeParts(3);
        ms = timeParts(4);

        t = h*3600 + ...
            m*60 + ...
            s + ms/1000;

        %% ID

        canID = hex2dec(idToken);

        %% Data

        hexBytes = regexp(dataToken, ...
            '[0-9A-Fa-f]{2}', ...
            'match');

        bytes = zeros(1,8);

        for k = 1:min(length(hexBytes),8)
            bytes(k) = hex2dec(hexBytes{k});
        end

        %% Store

        ID(end+1,1) = canID;
        Time(end+1,1) = t;
        Data(end+1,:) = bytes;

    end

    fclose(fid);

    % Normalize time to start at zero
    Time = Time - Time(1);

    T = table(ID, Time, Data);

end

